"use client";

import { createContext, useContext, useMemo, useSyncExternalStore } from "react";

export type Role = "PATIENT" | "DOCTOR" | "ADMIN";
export type Identity = { role: Role; userId: string; name: string };

type AuthValue = {
  identity: Identity | null;
  signIn: (identity: Identity) => void;
  signOut: () => void;
};

const AuthContext = createContext<AuthValue | null>(null);
const storageKey = "medicare.identity";
const listeners = new Set<() => void>();

function readIdentity(): Identity | null {
  if (typeof window === "undefined") return null;
  const raw = window.localStorage.getItem(storageKey);
  if (!raw) return null;
  try { return JSON.parse(raw) as Identity; } catch { window.localStorage.removeItem(storageKey); return null; }
}

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function notify() {
  listeners.forEach((listener) => listener());
}

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const identity = useSyncExternalStore(subscribe, readIdentity, () => null);
  const value = useMemo(() => ({
    identity,
    signIn: (next: Identity) => { window.localStorage.setItem(storageKey, JSON.stringify(next)); notify(); },
    signOut: () => { window.localStorage.removeItem(storageKey); notify(); },
  }), [identity]);
  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const value = useContext(AuthContext);
  if (!value) throw new Error("useAuth must be used inside AuthProvider");
  return value;
}
